```yaml
name: Update Roadmap on Merge

on:
  pull_request_target:
    types: [closed]
  push:
    branches: [main]

permissions:
  contents: write

jobs:
  update-roadmap:
    runs-on: ubuntu-latest
    if: github.event_name == 'push' || (github.event_name == 'pull_request_target' && github.event.pull_request.merged == true)
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Get last 10 merged PRs
        id: get_prs
        uses: actions/github-script@v6
        with:
          script: |
            const prs = await github.rest.pulls.list({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'closed',
              sort: 'updated',
              direction: 'desc',
              per_page: 100
            });
            const merged = prs.data.filter(pr => pr.merged_at).map(pr => pr.number);
            const recent = merged.slice(0, 10);
            core.setOutput('pr_numbers', recent.join('\n'));

      - name: Update roadmap file
        uses: actions/github-script@v6
        with:
          script: |
            const fs = require('fs');
            const path = 'roadmap.md';
            if (!fs.existsSync(path)) {
              core.setFailed(`File ${path} not found`);
              return;
            }
            let content = fs.readFileSync(path, 'utf8');

            // Build the new list of PRs
            const prNumbers = process.env.PR_NUMBERS.split('\n').filter(Boolean);
            const newList = prNumbers.map(num => `- #${num}`).join('\n');

            // Regex to find the section with the 10 most recent merged PRs
            const sectionRegex = /10 most recent \[merged PRs\]\(.*\):\n(?:- .*\n){10}/;
            const replacement = `10 most recent [merged PRs](https://github.com/sourcebot-dev/sourcebot/pulls?q=is%3Apr+is%3Amerged):\n${newList}\n`;

            if (!sectionRegex.test(content)) {
              core.setFailed('Could not find the roadmap section to replace.');
              return;
            }

            content = content.replace(sectionRegex, replacement);
            fs.writeFileSync(path, content);

            // Commit and push changes
            const { execSync } = require('child_process');
            execSync('git config user.name "github-actions[bot]"');
            execSync('git config user.email "github-actions[bot]@users.noreply.github.com"');
            execSync(`git add ${path}`);
            execSync('git commit -m "Update roadmap with recent merged PRs"');
            execSync('git push');
        env:
          PR_NUMBERS: ${{ steps.get_prs.outputs.pr_numbers }}
```

